properties.tools:
[
  {
    "name": "ask_owner",
    "ask": true,
    "description": "Ask the product owner one question with two to four options - the plans you drafted, one line each - and carry on with the one the owner picks. The owner's answer comes back as this call's result: one of the options, or the owner's own words.",
    "input_schema": {
      "type": "object",
      "properties": {
        "question": {
          "type": "string",
          "minLength": 1,
          "maxLength": 300
        },
        "options": {
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1,
            "maxLength": 200
          },
          "minItems": 2,
          "maxItems": 4
        }
      },
      "required": [
        "question",
        "options"
      ],
      "additionalProperties": false
    }
  }
]
